structureCode.vanilla:
// A barra inteira é declarada em dados: a factory monta lista, gatilhos e painéis.
const barra = createNavigationMenu(
  [
    { label: 'Início', href: '/' },
    {
      label: 'Produtos',
      children: [
        { label: 'Produto A', href: '/produtos/a' },
        { label: 'Produto B', href: '/produtos/b' },
      ],
    },
  ],
  { orientation: 'horizontal', delayDuration: 200 },
);
barra.setAttribute('aria-label', 'Navegação principal');

// Solta os ouvintes de ponteiro e de documento.
barra.destroy();

